test_setup_files.test_greeter_main.cpp:
#include "greeter.hpp"
#include <cassert>
#include <iostream>
#include <string>

int main() {
    std::string got = app::greet();
    std::string want = std::string("Hello, ") + app::NAME + "!";
    if (got != want) {
        std::cerr << "greet() = \"" << got << "\", want \"" << want
                  << "\" (the CURRENT app::NAME, not a stale value)" << std::endl;
        return 1;
    }
    std::cout << "PASS" << std::endl;
    return 0;
}

